import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.IOException;
import java.util.logging.Logger;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportType = req.getParameter("type");
        String dateRange = req.getParameter("range");
        String department = req.getParameter("dept");
        String sortCol = req.getParameter("sort");

        // Validate report type against allowed values
        if (reportType == null || !reportType.matches("(summary|detail|audit)")) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Validate date range format
        if (dateRange == null || !dateRange.matches("\\d{4}-\\d{2}-\\d{2}_\\d{4}-\\d{2}-\\d{2}")) {
            resp.sendError(400, "Invalid date range format");
            return;
        }

        // Department is optional, default to all
        if (department == null) {
            department = "%";
        }

        // Sort column - validated against whitelist... or so we think
        if (sortCol == null) {
            sortCol = "created_at";
        }

        String[] dates = dateRange.split("_");
        String startDate = dates[0];
        String endDate = dates[1];

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
            String query = buildReportQuery(reportType, startDate, endDate, department, sortCol);
            log.info("Executing report query for type=" + reportType);

            try (Statement stmt = conn.createStatement();
                 ResultSet rs = stmt.executeQuery(query)) {
                resp.setContentType("application/json");
                StringBuilder json = new StringBuilder("[\n");
                ResultSetMetaData meta = rs.getMetaData();
                int colCount = meta.getColumnCount();
                boolean first = true;
                while (rs.next()) {
                    if (!first) json.append(",\n");
                    json.append("  {");
                    for (int i = 1; i <= colCount; i++) {
                        if (i > 1) json.append(", ");
                        json.append("\"").append(meta.getColumnName(i)).append("\": ");
                        json.append("\"").append(rs.getString(i)).append("\"");
                    }
                    json.append("}");
                    first = false;
                }
                json.append("\n]");
                resp.getWriter().write(json.toString());
            }
        } catch (SQLException e) {
            log.severe("Database error: " + e.getMessage());
            resp.sendError(500, "Internal error");
        }
    }

    private String buildReportQuery(String type, String start, String end,
                                     String dept, String sortCol) {
        // type is validated above, dates are format-checked, dept uses LIKE
        String baseTable = type.equals("audit") ? "audit_log" : "reports";
        String query = "SELECT * FROM " + baseTable +
                " WHERE created_at BETWEEN '" + start + "' AND '" + end + "'" +
                " AND department LIKE '" + dept + "'" +
                " ORDER BY " + sortCol;
        return query;
    }

    @Override
    public void init() throws ServletException {
        try {
            Class.forName("org.postgresql.Driver");
        } catch (ClassNotFoundException e) {
            throw new ServletException("PostgreSQL driver not found", e);
        }
    }
}
